using System;using System.IO;using System.Linq;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.Rendering;using UnityEngine.Rendering.HighDefinition;
public static class TallGlazedHangar {
static Transform parent;static Material wood,grey,red,glass,roof;const string A="Assets/NewMap/TallHangar";
static GameObject Box(string n,Vector3 p,Vector3 s,Material m,bool collide=true){var g=GameObject.CreatePrimitive(PrimitiveType.Cube);g.name=n;g.transform.SetParent(parent,false);g.transform.localPosition=p;g.transform.localScale=s;g.GetComponent<Renderer>().sharedMaterial=m;if(!collide)UnityEngine.Object.DestroyImmediate(g.GetComponent<Collider>());return g;}
static void Beam(string n,Vector3 a,Vector3 b,float w){var g=Box(n,(a+b)*.5f,new Vector3(w,(b-a).magnitude,w),wood);g.transform.localRotation=Quaternion.FromToRotation(Vector3.up,b-a);}
static Material Mat(string n,Color c,float smooth){var m=new Material(Shader.Find("HDRP/Lit")){name=n};m.SetColor("_BaseColor",c);m.SetFloat("_Smoothness",smooth);HDMaterial.ValidateMaterial(m);AssetDatabase.CreateAsset(m,A+"/"+n+".mat");return m;}
static void SidePanel(int side,float z,float width,float y,float height){if(height<=0)return;Box("Grey interior wall panel",new Vector3(side*10,y,z),new Vector3(.18f,height,width),grey);Box("Red exterior cladding",new Vector3(side*10.13f,y,z),new Vector3(.10f,height,width),red);}
static void EndPanel(float z,float x,float width,float y,float height){Box("Grey end wall panel",new Vector3(x,y,z),new Vector3(width,height,.18f),grey);Box("Red exterior end cladding",new Vector3(x,y,z+Mathf.Sign(z)*.13f),new Vector3(width,height,.1f),red);}
static void Window(int side,float z){float x=side*9.86f,y=8.7f;var pane=Box("Glazed clerestory window",new Vector3(x,y,z),new Vector3(.035f,2.4f,2.5f),glass,false);pane.GetComponent<Renderer>().shadowCastingMode=ShadowCastingMode.Off;
foreach(float dz in new[]{-1.32f,0,1.32f})Box("Window oak mullion",new Vector3(x,y,z+dz),new Vector3(.22f,2.6f,.10f),wood);
foreach(float dy in new[]{-1.25f,0,1.25f})Box("Window oak transom",new Vector3(x,y+dy,z),new Vector3(.22f,.1f,2.75f),wood);}
static void RoofPiece(int side,float x0,float x1,float z0,float z1,bool glazed){float x=(x0+x1)*.5f;var g=Box(glazed?"Glass rooflight pane":"Grey roof panel",new Vector3(side*x,16-x*.4f,(z0+z1)*.5f),new Vector3((x1-x0)*Mathf.Sqrt(1.16f),glazed?.035f:.15f,z1-z0),glazed?glass:roof,!glazed);g.transform.localRotation=Quaternion.Euler(0,0,-side*Mathf.Atan(.4f)*Mathf.Rad2Deg);if(glazed)g.GetComponent<Renderer>().shadowCastingMode=ShadowCastingMode.Off;}
public static string Main(){
if(EditorApplication.isPlaying)throw new Exception("Edit mode required");var h=GameObject.Find("New_Map").transform.Find("01_Modular_Hangar");if(h.Find("Tall timber hall with glazing"))throw new Exception("Already authored");Directory.CreateDirectory(A);Directory.CreateDirectory("output/NewMap/TallHangar");AssetDatabase.Refresh();EditorSceneManager.SaveScene(UnityEngine.SceneManagement.SceneManager.GetActiveScene());Directory.CreateDirectory("Temp/NewMap");File.Copy("Assets/Scenes/Gameplay.unity","Temp/NewMap/Gameplay.before-tall-hangar.unity",true);
wood=h.Cast<Transform>().First(t=>t.name=="Clear span oak post").GetComponent<Renderer>().sharedMaterial;
foreach(Transform t in h){bool keep=t.name=="Concrete threshing floor"||t.name.Contains("Pendant")||t.name=="Warm pendant"||t.name=="Front softbox bounce"||t.name.StartsWith("Red barn exterior");if(!keep)t.gameObject.SetActive(false);}
var shell=h.Find("Red barn exterior - TFP_Barn_04A");foreach(Transform t in shell)if(t.name=="TFP_Barn_04A")t.gameObject.SetActive(false);
parent=new GameObject("Tall timber hall with glazing").transform;parent.SetParent(h,false);
AssetDatabase.StartAssetEditing();try{
grey=Mat("Warm grey wall panels",new Color(.32f,.34f,.35f),.18f);roof=Mat("Grey roof sheets",new Color(.28f,.31f,.33f),.28f);red=Mat("Weathered red exterior",new Color(.36f,.055f,.035f),.12f);glass=Mat("Clear blue window glass",new Color(.65f,.84f,.92f,.16f),.94f);glass.SetFloat("_SurfaceType",1);glass.SetFloat("_BlendMode",0);glass.SetFloat("_DoubleSidedEnable",1);glass.SetFloat("_TransparentZWrite",0);glass.SetFloat("_EnableBlendModePreserveSpecularLighting",1);glass.renderQueue=3000;HDMaterial.ValidateMaterial(glass);EditorUtility.SetDirty(glass);
// Five wall bays; the three middle bays have actual openings through both skins.
foreach(int side in new[]{-1,1})for(int i=0;i<5;i++){float z=-12+i*6;bool window=i>=1&&i<=3;if(window){SidePanel(side,z,6,3.75f,7.5f);SidePanel(side,z,6,10.95f,2.1f);SidePanel(side,z-2.125f,1.75f,8.7f,2.4f);SidePanel(side,z+2.125f,1.75f,8.7f,2.4f);Window(side,z);}else SidePanel(side,z,6,6,12);}
// Tall front portal: ten metres wide and nine metres clear beneath the lintel.
EndPanel(15,-7.5f,5,6,12);EndPanel(15,7.5f,5,6,12);EndPanel(15,0,10,10.5f,3);EndPanel(-15,0,20,6,12);
for(float x=-9.75f;x<10;x+=.5f){float height=4-Mathf.Abs(x)*.4f;EndPanel(15,x,.5f,12+height*.5f,height);EndPanel(-15,x,.5f,12+height*.5f,height);}
foreach(float z in new[]{-15f,-9f,-3f,3f,9f,15f}){
foreach(int side in new[]{-1,1}){Beam("Full height oak column",new Vector3(side*9.72f,0,z),new Vector3(side*9.72f,12,z),.34f);Beam("Timber roof rafter",new Vector3(side*9.72f,11.9f,z),new Vector3(0,15.8f,z),.28f);Beam("Oak knee brace",new Vector3(side*9.72f,9.5f,z),new Vector3(side*7.8f,11.9f,z),.22f);}Beam("High clear span tie beam",new Vector3(-9.72f,11.85f,z),new Vector3(9.72f,11.85f,z),.30f);}
foreach(int side in new[]{-1,1})foreach(float y in new[]{3.8f,7.2f,10.25f,11.9f})Box("Horizontal oak wall rail",new Vector3(side*9.79f,y,0),new Vector3(.24f,.18f,30),wood);
foreach(int side in new[]{-1,1})for(float z=-14.5f;z<15;z+=.65f){bool hole=(Mathf.Abs(z+6)<1.3f||Mathf.Abs(z)<1.3f||Mathf.Abs(z-6)<1.3f);if(!hole)Box("Subtle grey panel seam",new Vector3(side*9.88f,6,z),new Vector3(.035f,11.8f,.035f),roof,false);}
foreach(float x in new[]{-5.15f,5.15f})Box("Entrance oak jamb",new Vector3(x,4.5f,14.8f),new Vector3(.36f,9,.34f),wood);Box("Entrance oak lintel",new Vector3(0,9.15f,14.8f),new Vector3(10.6f,.32f,.34f),wood);
foreach(float z in new[]{-15f,15f})foreach(float y in new[]{3.8f,7.2f,11.9f}){if(z>0&&y<9){foreach(int side in new[]{-1,1})Box("End wall timber rail",new Vector3(side*7.6f,y,z-Mathf.Sign(z)*.22f),new Vector3(4.8f,.18f,.24f),wood);}else Box("End wall timber rail",new Vector3(0,y,z-Mathf.Sign(z)*.22f),new Vector3(20,.18f,.24f),wood);}
// Split the roof into solid sheets and two glazed bays on each slope.
foreach(int side in new[]{-1,1}){foreach(var span in new[]{new Vector2(-15,-5.5f),new Vector2(-2.5f,4.5f),new Vector2(7.5f,15)})RoofPiece(side,0,10.4f,span.x,span.y,false);foreach(float z in new[]{-4f,6f}){RoofPiece(side,0,3.5f,z-1.5f,z+1.5f,false);RoofPiece(side,6.5f,10.4f,z-1.5f,z+1.5f,false);RoofPiece(side,3.5f,6.5f,z-1.5f,z+1.5f,true);foreach(float x in new[]{3.5f,5f,6.5f})Beam("Rooflight longitudinal oak frame",new Vector3(side*x,16-x*.4f,z-1.55f),new Vector3(side*x,16-x*.4f,z+1.55f),.12f);foreach(float zz in new[]{z-1.5f,z,z+1.5f})Beam("Rooflight oak transom",new Vector3(side*3.5f,14.6f,zz),new Vector3(side*6.5f,13.4f,zz),.12f);}}
Beam("Oak ridge beam",new Vector3(0,15.9f,-15),new Vector3(0,15.9f,15),.3f);
// Retain the original red sliding doors as open exterior leaves.
foreach(int side in new[]{-1,1}){var door=Box("Open red sliding door",new Vector3(side*7.55f,4.4f,15.4f),new Vector3(4.9f,8.8f,.16f),red);foreach(float y in new[]{.3f,4.4f,8.5f})Box("Door timber rail",new Vector3(side*7.55f,y,15.52f),new Vector3(4.9f,.14f,.13f),wood);Beam("Door diagonal timber",new Vector3(side*5.2f,.4f,15.55f),new Vector3(side*9.9f,8.4f,15.55f),.15f);}
}finally{AssetDatabase.StopAssetEditing();}
foreach(Transform t in h){if(t.name=="Pendant shade"||t.name=="Warm pendant")t.position+=Vector3.up*2.4f;if(t.name=="Pendant cable"){var p=t.position;p.y=12.15f;t.position=p;var s=t.localScale;s.y=7.7f;t.localScale=s;}}
AssetDatabase.SaveAssets();EditorSceneManager.SaveScene(UnityEngine.SceneManagement.SceneManager.GetActiveScene());string report="Hall footprint 20 x 30m, wall height 12m (previously 7m), ridge 16m (previously 9.45m); clear portal 10m wide x 9m tall. Six glazed wall windows and four framed skylights with actual openings. Grey interior panels, timber structure, red exterior and retained native red wings. Player, truck and props remain unchanged.";File.WriteAllText("output/NewMap/TallHangar/summary.txt",report);return report;
}
}
